 function row(groups,rect,f,measureText,gap){const present=groups.filter(g=>g.length);if(!present.length)return[];const weights=present.map(group=>group.reduce((total,item)=>total+(item.type==='image'?clamp(rect.h*(item.aspect||1),rect.w*.08,rect.w*.55):clamp(measureText(String(item.text||''),preferredFont(item,f),item.weight||700)/2,rect.w*.08,rect.w*.45)),0));const space=rect.w-gap*(present.length-1),total=weights.reduce((a,b)=>a+b,0);let x=rect.x,result=[];for(let i=0;i<present.length;i++){const w=space*weights[i]/total;result.push(...pack(present[i],{x,y:rect.y,w,h:rect.h},f,measureText,gap));x+=w+gap;}return result;}
 function cohesionScore(layers,f){let penalty=0;const titles=layers.filter(l=>l.role==='text'),offers=layers.filter(l=>l.role==='offer'),small=Math.min(f.w,f.h);for(const title of titles){const a=pixels(title,f);let best=Infinity;for(const offer of offers){const b=pixels(offer,f),left=Math.max(a.x,b.x),right=Math.min(a.x+a.w,b.x+b.w);if(right-left<Math.min(a.w,b.w)*.4)continue;const top=Math.min(a.y+a.h,b.y+b.h),bottom=Math.max(a.y,b.y);if(bottom<=top)continue;const occupied=layers.some(l=>l.role==='image'&&overlap({x:left,y:top,w:right-left,h:bottom-top},pixels(l,f)));if(!occupied)best=Math.min(best,bottom-top);}if(Number.isFinite(best))penalty+=Math.min(2,Math.max(0,best/small-.04)*4);}return -penalty;}
