 function placeAroundLocked(l,occupied,f,gap){const original=pixels(l,f);if(!occupied.some(o=>overlap(original,o,gap/2)))return l;let best=null;for(let step=0;step<20;step++){const scale=Math.pow(.9,step),w=original.w*scale,h=original.h*scale;const xs=[original.x,gap,f.w-gap-w,...occupied.flatMap(o=>[o.x-w-gap,o.x+o.w+gap])],ys=[original.y,gap,f.h-gap-h,...occupied.flatMap(o=>[o.y-h-gap,o.y+o.h+gap])];for(const rawX of xs)for(const rawY of ys){const x=clamp(rawX,gap,f.w-gap-w),y=clamp(rawY,gap,f.h-gap-h),r={x,y,w,h};if(x<0||y<0||x+w>f.w||y+h>f.h||occupied.some(o=>overlap(r,o,gap/2)))continue;const loss=(Math.abs(x-original.x)/f.w+Math.abs(y-original.y)/f.h)+(1-scale)*3;if(!best||loss<best.loss)best={r,loss};}if(best)break;}if(!best)return{...l,layoutConflict:true};const r=best.r;return{...l,x:r.x/f.w,y:r.y/f.h,w:r.w/f.w,h:r.h/f.h};}
